CREATE DATABASE IF NOT EXISTS careerlens CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE careerlens;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(120) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resumes (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, original_name VARCHAR(255) NOT NULL, extracted_text MEDIUMTEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE job_descriptions (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, title VARCHAR(200), description MEDIUMTEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE analyses (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, resume_id BIGINT, job_description_id BIGINT, match_percentage TINYINT UNSIGNED NOT NULL, result_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(resume_id) REFERENCES resumes(id) ON DELETE SET NULL, FOREIGN KEY(job_description_id) REFERENCES job_descriptions(id) ON DELETE SET NULL);
CREATE TABLE candidate_skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, skill_name VARCHAR(120) NOT NULL, evidence TEXT, proficiency ENUM('beginner','intermediate','advanced','unspecified') NOT NULL DEFAULT 'unspecified', FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
CREATE TABLE job_skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, skill_name VARCHAR(120) NOT NULL, priority ENUM('high','medium','low') NOT NULL DEFAULT 'medium', FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
CREATE TABLE skill_gaps (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, skill_name VARCHAR(120) NOT NULL, category ENUM('matched','missing','improvement') NOT NULL, priority ENUM('high','medium','low') NOT NULL DEFAULT 'medium', FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
CREATE TABLE learning_roadmaps (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, week_number INT NOT NULL, stage ENUM('beginner','intermediate','advanced','learn','build','interview') NOT NULL, skill_name VARCHAR(120) NOT NULL, topics JSON NOT NULL, estimated_hours INT NOT NULL DEFAULT 0, FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
CREATE TABLE projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, difficulty ENUM('beginner','intermediate','advanced') NOT NULL, estimated_weeks INT NOT NULL, skills JSON NOT NULL, FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
CREATE TABLE interview_questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, analysis_id BIGINT NOT NULL, question TEXT NOT NULL, question_type ENUM('technical','behavioral') NOT NULL, focus_skill VARCHAR(120), expected_topics JSON NOT NULL, sample_answer TEXT, FOREIGN KEY(analysis_id) REFERENCES analyses(id) ON DELETE CASCADE);
